import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

  contract LandManager is BaseBlastManagerUpgradeable, ILandManager, ReentrancyGuard {

        // Existing contract code...

        function updateTaxRate(uint256 newTaxRate) external override notPaused nonReentrant {
            // Function implementation...
        }

        // Apply nonReentrant to other vulnerable functions as needed
    }
